function setPaused(value){paused=value;document.body.classList.toggle('motion-paused',paused);toggle.textContent=paused?'Motion off':'Pause motion';toggle.setAttribute('aria-pressed',String(!paused));stop();if(paused)reset();else start();}
toggle.onclick=()=>setPaused(!paused);

const observer=new IntersectionObserver(entries=>{for(const e of entries){const p=panels.find(p=>p.element===e.target);p.visible=e.isIntersecting;}if(panels.some(p=>p.visible))start();else stop();});
function resize(p){p.w=p.element.clientWidth;p.h=p.element.clientHeight;const d=Math.min(devicePixelRatio,1.5);p.canvas.width=p.w*d;p.canvas.height=p.h*d;p.ctx.setTransform(d,0,0,d,0,0);}
